import{d as p,C as s,o as d,c as g,a3 as t,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十六章","description":"《正易心法》第十六章——卦有反对，最为关键：反体既深、对体尤妙；吉凶祸福其实一体，代谢循环特倒正之间，乾坤坎离颐大过中孚小过八卦为造化之枢机。","frontmatter":{"title":"正易心法·第十六章","description":"《正易心法》第十六章——卦有反对，最为关键：反体既深、对体尤妙；吉凶祸福其实一体，代谢循环特倒正之间，乾坤坎离颐大过中孚小过八卦为造化之枢机。","category":"guide","aliases":["正易心法第十六章","卦有反对最为关键","对体八卦"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-16.md","filePath":"yijing/zheng-yi-xin-fa/chapter-16.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-16.md"},x=p({...c,setup(u){const i=[{id:"z16-01",label:"一、反对最为关键",showLabel:!0,sentences:[["卦有",{text:"反对",glossary:"fandui"},"，最为关键。",{text:"反体",glossary:"fanti"},"既深，",{text:"对体",glossary:"duiti"},"尤妙。"]],note:["卦有反卦与对卦，这是最关键的；反体已经深妙，对体尤其奇妙。（「反」是卦画上下翻转，即综卦；「对」是每一爻阴阳全反，即错卦。**这一章是全书反对体系的枢纽**——前面讲方法论，从本章起进入卦与卦之间的关系。）"]},{id:"z16-02",label:"二、圣人密意",showLabel:!0,sentences:[["世虽知有反对之说，不能知圣人",{text:"密意",glossary:"miyi"},"在是也。"]],note:["世人虽然知道有反对之说，却不能理解圣人的深意就在这里。（世人知道的是**技术操作**（翻转、阴阳全反，人人会做）；不知道的是**圣人为什么要这样编排**——这正是本章要揭示的「密意」。）"]},{id:"z16-03",label:"三、反二对四",showLabel:!0,sentences:[["盖二卦反而为二，对而为四。既列序之，又以",{text:"杂卦",glossary:"zaguaz"},"推明义者，以为天下之吉凶祸福，贫富贵贱，其实",{text:"一体",glossary:"yiti"},"也。"]],note:["两卦互为反卦就成为两卦，再加上对卦就成为四卦一组。《周易》既用卦序排列它们，又用《杂卦传》推演阐明其义——这是为了说明：天下的吉凶祸福、贫富贵贱，其实是一个整体。（**「二卦反而为二，对而为四」是结构，「其实一体」是义理**——圣人编排这个结构，是要说这件义理。这就是「密意」。）"]},{id:"z16-04",label:"四、代谢循环未始有常",showLabel:!0,sentences:[["别而言之，其",{text:"代谢循环",glossary:"daixie"},"，特倒正之间耳，",{text:"未始有常",glossary:"weishiYouchang"},"也。"]],note:["分开来说，它们的交替更迭、循环往复，不过是倒置与正立之间的差别，从来没有固定不变的。（**吉与凶只是同一个卦的「倒正之间」**：泰卦翻转是否卦，否卦翻转是泰卦——吉凶不是两样东西，是同一件事的两个朝向。这是《周易》「无常」观最精确的表达：不是悲观，不是乐观，而是「未始有常」。）"]},{id:"z16-05",label:"五、对体八卦",showLabel:!0,sentences:[["然反对则诸卦皆是，对体则乾、坤、坎、离、颐、大过、中孚、小过而已。"]],note:["然而反卦与对卦，六十四卦都有；但对体（翻转后卦体不变的卦），只有乾、坤、坎、离、颐、大过、中孚、小过这八卦。（这八卦的特点是**翻转 180 度后仍是自身**——乾䷀、坤䷁、坎䷜、离䷝（上下卦相同），颐䷚、大过䷛、中孚䷼、小过䷽（爻序为回文，正读反读一样）。）"]},{id:"z16-06",label:"六、造化之枢机",showLabel:!0,sentences:[["此八卦与诸卦不同，在《易》道，乃",{text:"死生寿夭",glossary:"sishengShouyao"},"造化之",{text:"枢机",glossary:"shuji"},"也。其体不变，故曰：对体尤妙。"]],note:["这八卦与其他卦不同，在《易》道中，是死生寿夭、造化的枢机所在。它们的卦体翻转后不变，所以说「对体尤妙」。（**枢机＝门轴**：普通卦有正有反，在转化中存在，是门扇；对体卦翻转后仍是自身，是门轴。**宇宙万物在吉凶祸福中循环转化（门扇开关），但必须有不变的枢轴支撑这个转化（门轴）。** 这八卦就是宇宙转化的不变支点。）"]}],o=[{id:"fandui",term:"反对",pinyin:"fǎn duì",meaning:"反卦（上下翻转，即综卦）与对卦（阴阳全反，即错卦）。"},{id:"fanti",term:"反体",pinyin:"fǎn tǐ",meaning:"翻转后的卦体。将卦画倒过来读，得到另一卦。"},{id:"duiti",term:"对体",pinyin:"duì tǐ",meaning:"阴阳全反的卦体。每一爻阴变阳、阳变阴，得到对卦。"},{id:"miyi",term:"密意",pinyin:"mì yì",meaning:"隐秘的深意。圣人编排《周易》卦序的深层用意。"},{id:"zaguaz",term:"杂卦",pinyin:"zá guà",meaning:"《杂卦传》，十翼之一，以对比方式说明卦义。"},{id:"yiti",term:"一体",pinyin:"yī tǐ",meaning:"同一个整体。吉凶祸福本是一体，非截然对立。"},{id:"daixie",term:"代谢循环",pinyin:"dài xiè xún huán",meaning:"交替更迭，循环往复。吉凶祸福的相互转化。"},{id:"weishiYouchang",term:"未始有常",pinyin:"wèi shǐ yǒu cháng",meaning:"从来没有固定不变的。吉凶无常，随时转化。"},{id:"sishengShouyao",term:"死生寿夭",pinyin:"sǐ shēng shòu yāo",meaning:"生死与长寿夭折。生命的根本问题。"},{id:"shuji",term:"枢机",pinyin:"shū jī",meaning:"门轴，转动的关键点。对体八卦是宇宙转化的不变支点。"}];return(b,a)=>{const l=s("DaoTextReading"),r=s("DaoKeywordCards");return d(),g("div",null,[a[0]||(a[0]=t(`<h1 id="正易心法·第十六章" tabindex="-1">正易心法·第十六章 <a class="header-anchor" href="#正易心法·第十六章" aria-label="Permalink to &quot;正易心法·第十六章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章揭示《周易》卦序编排的<strong>圣人密意</strong>，有三个层次：</p><p><strong>第一层（结构论）：反对是《周易》编排的密意</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>两卦互反 = 一组（二卦为二）</span></span>
<span class="line"><span>加上对卦 = 四卦一组（对而为四）</span></span>
<span class="line"><span>《杂卦传》也是按反对关系推明卦义的</span></span></code></pre></div><p><strong>第二层（哲学论）：吉凶祸福一体，代谢循环无常</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>反卦揭示：任何状态翻转就是其对立面（泰极否来，否极泰来）</span></span>
<span class="line"><span>对卦揭示：任何卦都有其完全对立的镜像（乾坤互为对卦）</span></span>
<span class="line"><span>= 「其实一体」——对立面本是同根</span></span>
<span class="line"><span>= 「代谢循环，特倒正之间耳，未始有常」</span></span></code></pre></div><p><strong>第三层（枢机论）：八个对体卦是造化枢机</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六十四卦中，只有八卦翻转后不变</span></span>
<span class="line"><span>这八卦是「稳定点」，是宇宙的枢轴</span></span>
<span class="line"><span>其他卦都在翻转变化，这八卦永远是自身 = 「其体不变」</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>八个对体卦</strong>：</p><table tabindex="0"><thead><tr><th>卦</th><th>结构</th><th>为什么不变</th></tr></thead><tbody><tr><td>乾 ☰☰</td><td>上下皆乾</td><td>六爻纯阳，翻转不变</td></tr><tr><td>坤 ☷☷</td><td>上下皆坤</td><td>六爻纯阴，翻转不变</td></tr><tr><td>坎 ☵☵</td><td>上下皆坎</td><td>上下相同 + 中爻对称</td></tr><tr><td>离 ☲☲</td><td>上下皆离</td><td>同上</td></tr><tr><td>颐 ䷚</td><td>上艮下震</td><td>六爻爻序为回文（阳阴阴阴阴阳）</td></tr><tr><td>大过 ䷛</td><td>上兑下巽</td><td>爻序为回文（阴阳阳阳阳阴）</td></tr><tr><td>中孚 ䷼</td><td>上巽下兑</td><td>爻序为回文</td></tr><tr><td>小过 ䷽</td><td>上震下艮</td><td>爻序为回文</td></tr></tbody></table><p><strong>为什么这八卦是「死生寿夭造化之枢机」？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾坤：纯阳纯阴，天地本体 → 万物生死的根本来源（第十章：圣贤之象）</span></span>
<span class="line"><span>坎离：天地中气，日月之体 → 日月交错生诸卦（第十四章）</span></span>
<span class="line"><span>颐：养也 → 颐养生命，寿夭之关键</span></span>
<span class="line"><span>大过：大者过也 → 超过常规，死生之际</span></span>
<span class="line"><span>中孚：信也，孚即孵化 → 生命孕育之象</span></span>
<span class="line"><span>小过：小者过也 → 调节之机，生死边缘</span></span></code></pre></div><p><strong>六个维度，涵盖生命的全部面向。</strong></p><p><strong>与第九章「伏象」的关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通卦：有伏象（对立面是另一个卦）</span></span>
<span class="line"><span>对体卦：伏象就是自身（对立面统一于自身）</span></span></code></pre></div><p><strong>这正是为什么对体卦是「枢机」</strong>：它们已经内含了对立统一，不需要通过转化来实现，本身就是完整的。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把「反」与「对」两个操作弄清楚（翻转 vs 阴阳全反）；</li><li>再读「其实一体」——<strong>这是全章的义理核心</strong>；</li><li>最后看八个对体卦：<strong>它们是唯一「没有另一个对立面」的卦。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>反与对</strong>：翻转（综）与阴阳全反（错）。</li><li><strong>反二对四</strong>：反卦成对，对卦成组。</li><li><strong>其实一体</strong>：吉凶祸福本是一个整体。</li><li><strong>未始有常</strong>：代谢循环，只在倒正之间。</li><li><strong>对体八卦</strong>：乾坤坎离颐大过中孚小过。</li><li><strong>造化枢机</strong>：其体不变，故为枢轴。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,23)),e(l,{colophon:"反对关键 · 吉凶一体 · 代谢循环 · 对体尤妙",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十六章原文",sections:i,glossary:o}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"反体 · 对体",pinyin:["fǎn","duì"],meaning:"反体＝卦画上下翻转（综卦）；对体＝每一爻阴阳全反（错卦）。前者说「二卦反而为二」，后者说「对而为四」。"},{term:"圣人密意",pinyin:["mì","yì"],meaning:"世人知道「反对」的技术操作，不知道圣人为何这样编排——密意即「吉凶祸福其实一体」。"},{term:"其实一体",pinyin:["qí","shí"],meaning:"吉凶祸福、贫富贵贱本是一个整体。吉与凶只是同一卦的「倒正之间」，非两样东西。"},{term:"未始有常",pinyin:["wèi","shǐ"],meaning:"从来没有固定不变的。不是悲观也不是乐观，而是「吉凶本一体、转化在倒正之间」。"},{term:"对体八卦",pinyin:["duì","tǐ"],meaning:"乾坤坎离（上下卦相同）＋颐大过中孚小过（爻序为回文）——翻转 180 度后仍是自身，是六十四卦中唯一「没有另一个对立面」的卦。"},{term:"造化之枢机",pinyin:["shū","jī"],meaning:"枢机即门轴。普通卦是门扇（有正有反），对体卦是门轴（体不变）——宇宙转化的不变支点。"}]}),a[3]||(a[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章揭示《周易》卦序编排的<strong>圣人密意</strong>，三个层次：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>结构论：反二对四（反对关系的结构编排）</span></span>
<span class="line"><span>哲学论：其实一体，代谢循环，未始有常</span></span>
<span class="line"><span>枢机论：八个对体卦是造化枢机</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「世虽知有反对之说」——知与不知的差别</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>世人知道的：反卦 = 卦画翻转；对卦 = 阴阳全反（技术操作）</span></span>
<span class="line"><span>世人不知道的：圣人用反对编排卦序，是在说「吉凶祸福本是一体」</span></span></code></pre></div><p><strong>为什么对体卦是「枢机」？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通卦（可反的卦）：有正有反，在转化中存在 = 门扇（会开会关）</span></span>
<span class="line"><span>对体卦（不可反的卦）：翻转后仍是自身 = 门轴（永远在原位，支撑门扇转动）</span></span></code></pre></div><p><strong>宇宙的运行</strong>：万物在吉凶祸福中循环转化（门扇开关），但必须有不变的枢轴支撑这个转化（门轴）。</p><p><strong>与第九章「伏象」的关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通卦：有伏象（对立面是另一个卦）</span></span>
<span class="line"><span>对体卦：伏象就是自身（对立面统一于自身）</span></span></code></pre></div><p><strong>这正是为什么对体卦是「枢机」</strong>——它们已经内含了对立统一，本身就是完整的。</p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>拿泰䷊和否䷋ 试一次：<strong>翻转、阴阳全反，看它们怎么互为反卦与对卦</strong>；</li><li>记住「门扇与门轴」的比喻：<strong>变化的是门扇，不变的是门轴</strong>；</li><li>带着一个问题往下读：<strong>我生命里，哪些是「可反的卦」（会翻转的状态），哪些是我的「对体」（不变的那个）？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>卦有反卦与对卦，这是最关键的；反体已经深妙，对体尤其奇妙。</p><p>世人虽然知道有反对之说，却不能理解圣人的深意就在这里。</p><p>两卦互为反卦就成为两卦，再加上对卦就成为四卦一组。《周易》既用卦序排列它们，又用《杂卦传》推演阐明其义——这是为了说明：天下的吉凶祸福、贫富贵贱，其实是一个整体。</p><p>分开来说，它们的交替更迭、循环往复，不过是倒置与正立之间的差别，从来没有固定不变的。</p><p>然而反卦与对卦，六十四卦都有；但对体（翻转后不变的卦），只有乾、坤、坎、离、颐、大过、中孚、小过这八卦。</p><p>这八卦与其他卦不同，在《易》道中，是死生寿夭、造化的枢机所在。它们的卦体翻转后不变，所以说「对体尤妙」。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第十六章的密意是——<strong>吉凶不是两样东西，是同一个东西的两个朝向；六十四卦里只有八个「翻过来还是自己」，它们就是宇宙的门轴。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「二卦反而为二，对而为四」</strong>——这是<strong>结构</strong>；「其实一体」是<strong>义理</strong>。<strong>圣人先做结构，再让结构说出义理。</strong> 这种「用结构讲道理」的方式，比用文字讲更硬。</li><li><strong>「其代谢循环，特倒正之间耳」</strong>——这句话是全章最重的一句。<strong>吉凶祸福、贫富贵贱，不是命运的两种结果，是同一个东西的两种朝向。</strong> 我读到这句时想到的，不是「乐观」，而是**「不必急着判好坏」**。</li><li><strong>「未始有常」</strong>——不是悲观世事无常，而是说<strong>从来就没有固定不变的东西</strong>。这与《老子》「祸兮福之所倚」是同一个意思，但麻衣是用卦画结构说出来的。</li><li><strong>「门扇与门轴」</strong>——这个比喻我自己很喜欢。<strong>变的是门扇，不变的是门轴。</strong> 那么我的门轴是什么？</li><li><strong>八个对体卦</strong>——它们是六十四卦里唯一「没有另一个对立面」的卦。<strong>这个「没有对立面」不是缺陷，是完整。</strong> 一个已经内含了对立统一的卦，不需要通过翻转来实现自己。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>颐（实两端、虚中间，口的形状）与中孚（虚两端、实中间，蛋的形状）——一个「口」，一个「蛋」；口是摄入（养），蛋是孕育（生）。这两个形状与「死生寿夭」有什么关系？</strong> 我的想法：<strong>颐是「已生之后的养」，中孚是「未生之前的孕」；颐（口）是生命向外的摄取，中孚（蛋）是生命向内的凝聚。</strong> 两卦一开一合，正好把「生」的两端（未生／已生）夹住——<strong>这可能就是它们进入「造化枢机」的原因：它们守着生命的进出口。</strong> 这个推论未必是定论，但它是从卦画形状推出来的，不是从旧注背来的。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-08">第八章 · 纵横施设</a> — 「对待之理」与「错综之占」（本章的总纲出处）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-09">第九章 · 乃生六子</a> — 伏象（本章「对体」是其特例）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-15">第十五章 · 凡健皆乾</a> — 方法论部分的收束（本章开启反对体系）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-18">第十八章</a> — 「名义无不反对」的具体展开</li><li><a href="/Dao/yijing/shi-yi/za-gua-zhuan">杂卦传</a> — 以对比方式说卦义（本章说明其所以然）</li><li><a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a> — 义理相因的线性叙述（本章提出「结构对称」的另一层）</li></ul>`,28))])}}});export{y as __pageData,x as default};
